import useExplorer from '@cetus/hooks/src/useExplorer'
import { useGetToken } from '@cetus/hooks/src/useToken'
import { CoinType, Token } from '@cetus/types'
import { SingleCoinImage } from '@cetus/ui-kit'
import { cancelBubble, isAvailableObject, textEllipses } from '@cetus/utils'
import { Box, CenterProps, HStack, HTMLChakraProps, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import { AddressCopyLink, CetusTooltip } from '../../index'

// 没有token信息时可以只传coin_type
interface SingleTokenInfoProps extends HTMLChakraProps<'div'> {
  token?: any
  coinType?: string
  imgBoxStyle?: CenterProps
  symbolFontSize?: string
  symbolFontWeight?: string
  haveTooltip?: boolean
  haveName?: boolean
  haveSymbol?: boolean
  haveAddress?: boolean
  addressAbridgeStyle?: string
  symbolEllipsesDecimals?: number //symbol超过多少位展示... 值为0展示全部
  nameEllipsesDecimals?: number
  isCancelBubble?: boolean
  warningIcon?: {
    isNeedShow?: boolean
    iconW?: string
    iconH?: string
  }
}

const getTokenName = (tokenInfo: Token) => {
  if (tokenInfo?.coin_type) {
    switch (tokenInfo?.coin_type) {
      case '0x5d4b302506645c37ff133b98c4b50a5ae14841659738d6d733d59d0d217a93bf::coin::COIN':
        return 'Portal from Eth'
      case '0xc060006111016b8a020ad5b33834984a437aaa7d3c74c18e09a95d48aceab08c::coin::COIN':
        return 'Portal from Eth'
      default:
        return tokenInfo.name
    }
  }
}
const SingleTokenInfo = ({
  token,
  coinType,
  imgBoxStyle = {},
  symbolFontSize = '14px',
  symbolFontWeight = '500',
  haveTooltip = false,
  haveName = true,
  haveSymbol = true,
  warningIcon = {},
  haveAddress = false,
  addressAbridgeStyle,
  symbolEllipsesDecimals = 10,
  nameEllipsesDecimals = 28,
  isCancelBubble = false,
  ...rest
}: SingleTokenInfoProps) => {
  const { getTokenInfo } = useGetToken()
  const [tokenInfo, setTokenInfo] = useState<any>(token)
  const { isNeedShow = true, iconW = '16px', iconH = '16px' } = warningIcon

  const fetchToken = async () => {
    if (!coinType) return
    try {
      const coinInfo = await getTokenInfo(coinType as CoinType)
      console.log('🚀 ~ fetchToken ~ coinInfo:', coinType, coinInfo)
      if (coinInfo) {
        setTokenInfo(coinInfo)
      }
    } catch (error) {
      console.error('Error fetching token info:', error)
    }
  }
  useEffect(() => {
    fetchToken()
  }, [coinType])

  useEffect(() => {
    if (isAvailableObject(token)) {
      setTokenInfo(token)
    }
  }, [token?.coin_type])

  const { getExplorerUrl } = useExplorer()
  return (
    <Box onClick={isCancelBubble ? (e: any) => cancelBubble(e) : () => {}}>
      <HStack {...rest}>
        <VStack align="flex-start" gap="0">
          <CetusTooltip
            placement="top"
            showTooltip={haveTooltip ? true : false}
            tooltip={
              <HStack>
                <SingleCoinImage
                  imageUrl={tokenInfo?.logo_url}
                  w="20px"
                  h="20px"
                  minH="20px"
                  minW="20px"
                  showTag={isNeedShow}
                  showTagWidth="10px"
                  showTagHeight="10px"
                  coinType={tokenInfo ? tokenInfo?.coin_type : ''}
                />
                <Text color="text_caption"> {textEllipses(tokenInfo?.symbol, symbolEllipsesDecimals)}</Text>
                <AddressCopyLink address={tokenInfo?.coin_type} onClickLink={() => window.open(getExplorerUrl(tokenInfo?.coin_type, 'coin'))} />
              </HStack>
            }
          >
            <HStack>
              <SingleCoinImage
                imageUrl={tokenInfo?.logo_url}
                imgBoxStyle={imgBoxStyle}
                coinType={tokenInfo?.coin_type}
                showTag={isNeedShow}
                showTagHeight={iconH}
                showTagWidth={iconW}
              />
              {(haveSymbol || haveName || haveAddress) && (
                <VStack align="flex-start" gap="0px">
                  {haveSymbol && (
                    <Text color="text_caption" fontSize={symbolFontSize} fontWeight={symbolFontWeight} textAlign="left">
                      {textEllipses(tokenInfo?.symbol, symbolEllipsesDecimals)}
                    </Text>
                  )}
                  {haveName && (
                    <Text textAlign="left" fontSize="12px" mt="4px">
                      {textEllipses(getTokenName(tokenInfo), nameEllipsesDecimals)}
                    </Text>
                  )}
                  {haveAddress && (
                    <AddressCopyLink
                      address={tokenInfo?.coin_type}
                      addressAbridgeStyle={addressAbridgeStyle}
                      showLink={false}
                      onClickLink={() => window.open(getExplorerUrl(tokenInfo?.coin_type, 'coin'))}
                    />
                  )}
                </VStack>
              )}
            </HStack>
          </CetusTooltip>
        </VStack>
      </HStack>
    </Box>
  )
}

export default SingleTokenInfo
